class SQLCompiler:
    async def aiterator(self, chunk_size=2000):
        """Async iterator that fetches results directly from database."""
        # Use async database driver if available
        if hasattr(self.connection, 'aiterator'):
            async for row in self.connection.aiterator(self.query, chunk_size):
                yield row
        else:
            # Fallback to sync bridge
            sync_iter = self.results_iter()
            def next_chunk():
                return list(islice(sync_iter, chunk_size))
            while True:
                chunk = await sync_to_async(next_chunk)()
                for item in chunk:
                    yield item
                if len(chunk) < chunk_size:
                    break
